     "summary": "本案系广东高院2025年度商事金融典型创投纠纷案。投资方分三期共6000万元认购科技公司股权，第三期4200万元投资款以核心人员稳定、企业正常经营为付款前置条件。此后，企业核心人员离职、经营恶化，创始股东起诉索要该笔款项及违约金。法院依据协议及《民法典》先履行抗辩权相关规定驳回诉请。该案明确了Earnout分期投资模式的效力，提示投融资双方重视协议前置条件，平衡投融资风险。",
